import Phaser from 'phaser';

/**
 * Load pilot portrait texture atlases.
 *
 * Each atlas is a 1024×768 sprite sheet with two 512×768 frames:
 *   'base' — idle portrait (column 0)
 *   'talk' — talking portrait (column 1)
 *
 * Generated by Aseprite via scripts/gen_portrait_atlases.ts.
 * Missing sheets fail silently — Phaser skips 404s without error.
 *
 * @param loader - The Phaser loader plugin from the calling scene (this.load).
 */
export function loadPortraitImages(loader: Phaser.Loader.LoaderPlugin): void {
  // COMMAND speaker — single image, no talk animation
  loader.image('portrait_command', 'assets/portraits/portrait_command.png');

  // Terran Hegemony
  loader.atlas('portrait_admiral_chen', 'assets/portraits/terran_hegemony/admiral_chen_sheet.png', 'assets/portraits/terran_hegemony/admiral_chen_sheet.json');
  loader.atlas('portrait_striker',      'assets/portraits/terran_hegemony/striker_sheet.png',      'assets/portraits/terran_hegemony/striker_sheet.json');
  loader.atlas('portrait_whisper',      'assets/portraits/terran_hegemony/whisper_sheet.png',      'assets/portraits/terran_hegemony/whisper_sheet.json');

  // Free Confederation
  loader.atlas('portrait_commander_santos', 'assets/portraits/free_confederation/commander_santos_sheet.png', 'assets/portraits/free_confederation/commander_santos_sheet.json');
  loader.atlas('portrait_phoenix_one',      'assets/portraits/free_confederation/phoenix_one_sheet.png',      'assets/portraits/free_confederation/phoenix_one_sheet.json');
  loader.atlas('portrait_doc_vasquez',      'assets/portraits/free_confederation/doc_vasquez_sheet.png',      'assets/portraits/free_confederation/doc_vasquez_sheet.json');

  // Synthetic Collective
  loader.atlas('portrait_omega_7',          'assets/portraits/synthetic_collective/omega_7_sheet.png',          'assets/portraits/synthetic_collective/omega_7_sheet.json');
  loader.atlas('portrait_prime_collective', 'assets/portraits/synthetic_collective/prime_collective_sheet.png', 'assets/portraits/synthetic_collective/prime_collective_sheet.json');
  loader.atlas('portrait_unit_zero',        'assets/portraits/synthetic_collective/unit_zero_sheet.png',        'assets/portraits/synthetic_collective/unit_zero_sheet.json');

  // Void Corsairs
  loader.atlas('portrait_captain_kira', 'assets/portraits/void_corsairs/captain_kira_sheet.png', 'assets/portraits/void_corsairs/captain_kira_sheet.json');
  loader.atlas('portrait_the_admiral',  'assets/portraits/void_corsairs/the_admiral_sheet.png',  'assets/portraits/void_corsairs/the_admiral_sheet.json');
  loader.atlas('portrait_bloodfang',    'assets/portraits/void_corsairs/bloodfang_sheet.png',    'assets/portraits/void_corsairs/bloodfang_sheet.json');

  // Ascendant Empire
  loader.atlas('portrait_the_dreamer',      'assets/portraits/ascendant_empire/the_dreamer_sheet.png',      'assets/portraits/ascendant_empire/the_dreamer_sheet.json');
  loader.atlas('portrait_archon_zaelthar',  'assets/portraits/ascendant_empire/archon_zaelthar_sheet.png',  'assets/portraits/ascendant_empire/archon_zaelthar_sheet.json');
  loader.atlas('portrait_herald',           'assets/portraits/ascendant_empire/herald_sheet.png',           'assets/portraits/ascendant_empire/herald_sheet.json');
}
